authors.example:
extend schema
  @link(url: "https://specs.apollo.dev/federation/v2.6", import: ["@composeDirective"])
  @link(url: "https://specs.graphql-mesh.dev/rate-limit/v0.1", import: ["@rateLimit"])
  @composeDirective(name: "@rateLimit")

type Query {
  search(q: String!): [Item!]!
    @rateLimit(max: 10, window: "1s", identityArgs: ["q"])
}
